//! Compile check for the Rust generator's emitted output: each committed golden is
//! generated code (see rust/rustgen-golden/README or tests/test_rustgen.cpp), included
//! under its own module so a schema's `arena`/`common` trees are siblings, matching how
//! a consumer includes one schema's generated file. Generated by the `[rustgen-golden]`
//! test from the no-import corpus; regenerate with tests/regen_goldens.sh.
#![cfg_attr(not(feature = "std"), no_std)]
#![allow(clippy::all)]
// Generated code: `unused` covers dead_code and the stubbed `decode`'s unused params;
// the casing allows fire only for schemas whose own proto names are unconventional (the
// emitter preserves proto names rather than re-casing them).
#![allow(unused)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(non_upper_case_globals)]

